#include <stdio.h>
#include <time.h>

int main() {
    clock_t start = clock();
    // Simulate some work with a simple loop
    for(volatile int i = 0; i < 1000000000; i++);
    clock_t end = clock();
    double time_spent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Time spent: %f seconds\n", time_spent);
    return 0;
}
